this.router.events.pipe(
      filter((event): event is NavigationEnd => event instanceof NavigationEnd),
    ).subscribe

this.stateService.keyNavigation$
      .pipe(
        filter((event) => event.key === prevKey || event.key === nextKey),
        tap((event) => {
          if (event.key === prevKey && this.page > 1) {
            this.page--;
            this.isLoading = true;
            this.cd.markForCheck();
          }
          if (event.key === nextKey && this.page * 15 < this.blocksCount) {
            this.page++;
            this.isLoading = true;
            this.cd.markForCheck();
          }
        }),
        throttleTime(1000, undefined, { leading: true, trailing: true }),
      ).subscribe

this.route.paramMap.pipe(
      switchMap((params) => {
        const id = params.get('id');
        if (id) {
          return this.api.getWildkinCreature$(id).pipe(
            switchMap((creature) => of<CreaturesViewModel>({ kind: 'detail', selected: creature })),
            catchError(() => of<CreaturesViewModel>({ kind: 'error' }))
          );
        }
        return this.api.getWildkinCreatures$().pipe(
          switchMap((data) => of<CreaturesViewModel>({ kind: 'ready', creatures: data.creatures })),
          catchError(() => of<CreaturesViewModel>({ kind: 'error' }))
        );
      })
    ).subscribe

this.route.paramMap.pipe(
      switchMap((params) => {
        const tokenId = params.get('tokenId');
        if (tokenId) {
          return this.api.getCat20Token$(tokenId).pipe(
            switchMap((token) => {
              return this.api.getCat20Holders$(token.tokenId).pipe(
                switchMap((h) => of<Cat20ViewModel>({ kind: 'detail', selected: token, holders: h.holders })),
                catchError(() => of<Cat20ViewModel>({ kind: 'detail', selected: token, holders: [] }))
              );
            }),
            catchError(() => of<Cat20ViewModel>({ kind: 'error' }))
          );
        }
        return this.api.getCat20Tokens$().pipe(
          switchMap((data) => of<Cat20ViewModel>({ kind: 'ready', tokens: data.tokens })),
          catchError(() => of<Cat20ViewModel>({ kind: 'error' }))
        );
      })
    ).subscribe

this.api.executeDataQuery$({
      datasetId: this.selectedDatasetId,
      limit: this.queryLimit,
    }).pipe(
      catchError(() => of(null))
    ).subscribe

this.route.paramMap.pipe(
      switchMap((params) => {
        const assetId = params.get('assetId');
        if (assetId) {
          return this.api.getTaprootAsset$(assetId).pipe(
            switchMap((asset) => of<TaprootViewModel>({ kind: 'detail', selected: asset })),
            catchError(() => of<TaprootViewModel>({ kind: 'error' }))
          );
        }
        return combineLatest([
          this.api.getTaprootAssets$().pipe(catchError(() => of({ assets: [] }))),
          this.api.getTaprootAssetGroups$().pipe(catchError(() => of({ groups: [] }))),
        ]).pipe(
          switchMap(([assetsData, groupsData]) => of<TaprootViewModel>({
            kind: 'ready',
            assets: assetsData.assets,
            groups: groupsData.groups,
          })),
          catchError(() => of<TaprootViewModel>({ kind: 'error' }))
        );
      })
    ).subscribe

this.api.networkChanges$.pipe(startWith(this.api.network), distinctUntilChanged(), switchMap(() => {
        this.loading = true; this.overview = null; this.error = null;
        return this.api.getCoverage$().pipe(catchError(err => {
          this.error = err?.error?.reason || err?.error?.error || 'First-party coverage source is unavailable.';
          this.loading = false; this.cd.markForCheck(); return EMPTY;
        }));
      })).subscribe

this.api.networkChanges$.pipe(startWith(this.api.network), distinctUntilChanged(), switchMap(() => {
