this.route.paramMap
      .pipe(switchMap((params) => {
        // The same view answers /mempool/clusters/:clusterId and
        // /tx/:txid/package. They are the same object reached two ways, so
        // they share one page rather than diverging into two.
        const txid = params.get('txid');
        this.reference = txid ?? params.get('clusterId') ?? '';
        this.fromTransaction = !!txid;
        this.loading = true;
        this.error = null;
        this.seo.setTitle(txid
          ? $localize`:@@mempool.package.title:Transaction package`
          : $localize`:@@mempool.cluster.title:Mempool cluster`);
        return txid
          ? this.api.getMempoolPackage$(txid)
          : this.api.getMempoolCluster$(this.reference);
      }))
      .subscribe

this.api.simulate$({
      scenario: this.scenario,
      attacker_slots: this.attackerSlots,
      enable_reputation: this.enableReputation,
      enable_fast_lane: this.enableFastLane,
    }).subscribe

this.stateService.serverHealth$.pipe(
      map((hosts) => {
        const subpath = window.location.pathname.slice(0, -6);
        for (const host of hosts) {
          let statusUrl = '';
          let linkHost = '';
          if (host.socket) {
            statusUrl = 'https://' + window.location.hostname + subpath + '/status';
            linkHost = window.location.hostname + subpath;
          } else {
            const hostUrl = new URL(host.host);
            statusUrl = 'https://' + hostUrl.hostname + subpath + '/status';
            linkHost = hostUrl.hostname + subpath;
          }
          host.statusPage = this.sanitizer.bypassSecurityTrustResourceUrl(this.sanitizer.sanitize(SecurityContext.URL, statusUrl));
          host.link = linkHost;
        }
        return hosts;
      }),
      tap((hosts) => {
        if (this.hosts.length !== hosts.length) {
          this.hosts = hosts.sort((a,b) => {
            const aParts = (a.host?.split('.') || []).reverse();
            const bParts = (b.host?.split('.') || []).reverse();
            let i = 0;
            while (i < Math.max(aParts.length, bParts.length)) {
              if (aParts[i] && !bParts[i]) {
                return 1;
              } else if (bParts[i] && !aParts[i]) {
                return -1;
              } else if (aParts[i] !== bParts[i]) {
                return aParts[i].localeCompare(bParts[i]);
              }
              i++;
            }
            return 0;
          });
        }
        this.cd.markForCheck();
      })
    ).subscribe

this.servicesApiService.getSimpleProofs$(this.key).pipe(
        catchError(() => {
          this.isLoading = false;
          this.error = true;
          return of({});
        }),
      ).subscribe

this.servicesApiService.getSimpleProofs$(this.key).pipe(
        catchError(() => {
          this.isLoading = false;
          this.error = true;
          return of({});
        }),
      ).subscribe

this.route.queryParamMap
      .pipe(
        switchMap((params: ParamMap) => {
          this.error = undefined;
          this.isLoadingAddress = true;
          this.addresses = {};
          this.addressInfo = {};
          this.balance = 0;

          this.addressStrings = params.get('addresses').split(',').map(address => {
            if (/^[A-Z]{2,5}1[AC-HJ-NP-Z02-9]{8,100}|04[a-fA-F0-9]{128}|(02|03)[a-fA-F0-9]{64}$/.test(address)) {
              return address.toLowerCase();
            } else {
              return address;
            }
          });

          return forkJoin(this.addressStrings.map(address => {
            const getLiquidInfo = ((this.stateService.network === 'liquid' || this.stateService.network === 'liquidtestnet') && /^([a-zA-HJ-NP-Z1-9]{26,35}|[a-z]{2,5}1[ac-hj-np-z02-9]{8,100}|[a-km-zA-HJ-NP-Z1-9]{80})$/.test(address));
            return forkJoin([
              of(address),
              this.electrsApiService.getAddress$(address),
              (getLiquidInfo ? this.apiService.validateAddress$(address) : of(null)),
            ]);
          }));
        }),
        catchError(e => {
          this.error = e;
          return of([]);
        })
      ).subscribe

this.route.paramMap.pipe(
      switchMap((params: ParamMap) => {
        const rawMode: string = params.get('mode');
        const mode = rawMode === 'mempool' ? 'mempool' : 'mined';
        const index: number = Number.parseInt(params.get('index'));
        if (mode !== rawMode || index < 0 || isNaN(index)) {
          this.router.navigate([this.relativeUrlPipe.transform('/clock'), mode, index || 0]);
        }
        return of({
          mode,
          index,
        });
      }),
      tap((page: { mode: 'mempool' | 'mined', index: number }) => {
        this.mode = page.mode;
        this.blockIndex = page.index || 0;
        if (this.blocks[this.blockIndex]) {
          this.blockStyle = this.getStyleForBlock(this.blocks[this.blockIndex]);
          this.cd.markForCheck();
        }
      })
    ).subscribe

this.route.paramMap
      .pipe(
        switchMap((params: ParamMap) => {
          this.index = parseInt(params.get('index'), 10) || 0;
          return this.stateService.mempoolBlocks$
            .pipe(
              map((blocks) => {
                if (!blocks.length) {
                  return [{ index: 0, blockSize: 0, blockVSize: 0, feeRange: [0, 0], medianFee: 0, nTx: 0, totalFees: 0 }];
                }
                return blocks;
              }),
              filter((mempoolBlocks) => mempoolBlocks.length > 0),
              tap((mempoolBlocks) => {
                while (!mempoolBlocks[this.index]) {
                  this.index--;
                }
              })
            );
        })
      ).subscribe

this.router.events
      .pipe(
        takeUntilDestroyed(),
        filter((event) => event instanceof NavigationEnd),
        map(() => {
          const segments = this.router.url.split('?')[0].split('/');
          const index = segments.indexOf('p');
          return index >= 0 && segments.length > index + 2 ? segments[index + 2] : 'overview';
        }),
      )
      .subscribe

this.apiService.postTransaction$(this.rawHexTransaction).pipe(
      tap((txid: string) => {
        this.isLoadingBroadcast = false;
        this.successBroadcast = true;
        this.transaction.txid = txid;
      }),
      switchMap((txid: string) =>
        timer(2000).pipe(
          tap(() => this.router.navigate([this.relativeUrlPipe.transform('/tx/' + txid)])),
        )
      ),
      catchError((error) => {
        if (typeof error.error === 'string') {
          const matchText = error.error.replace(/\\/g, '').match('"message":"(.*?)"');
          this.errorBroadcast = 'Failed to broadcast transaction, reason: ' + (matchText && matchText[1] || error.error);
        } else if (error.message) {
          this.errorBroadcast = 'Failed to broadcast transaction, reason: ' + error.message;
        }
        this.isLoadingBroadcast = false;
        return throwError(() => error);
      })
    ).subscribe

this.zoneService.wrapObservable(this.route.paramMap
      .pipe(
        switchMap((params: ParamMap) => {
          const urlMatch = (params.get('id') || '').split(':');
          if (urlMatch.length === 2 && urlMatch[1].length === 64) {
            const vin = parseInt(urlMatch[0], 10);
            this.txId = urlMatch[1];
            // rewrite legacy vin syntax
            if (!isNaN(vin)) {
              this.fragmentParams.set('vin', vin.toString());
              this.fragmentParams.delete('vout');
            }
            this.router.navigate([this.relativeUrlPipe.transform('/tx'), this.txId], {
              queryParamsHandling: 'merge',
              fragment: this.fragmentParams.toString(),
            });
          } else {
            this.txId = urlMatch[0];
            const vout = parseInt(urlMatch[1], 10);
            if (urlMatch.length > 1 && !isNaN(vout)) {
              // rewrite legacy vout syntax
              this.fragmentParams.set('vout', vout.toString());
              this.fragmentParams.delete('vin');
              this.router.navigate([this.relativeUrlPipe.transform('/tx'), this.txId], {
                queryParamsHandling: 'merge',
                fragment: this.fragmentParams.toString(),
              });
            }
          }
          if (this.network === '' && this.txId) {
            this.duplicateTxBlocks = DUPLICATE_TX_BLOCKS[this.txId?.toLowerCase()];
          }
          if (window.innerWidth <= 767.98) {
            this.router.navigate([this.relativeUrlPipe.transform('/tx'), this.txId], {
              queryParamsHandling: 'merge',
              preserveFragment: true,
              queryParams: { mode: 'details' },
              replaceUrl: true,
            });
          }
          this.seoService.setTitle(
            $localize`:@@bisq.transaction.browser-title:Transaction: ${this.txId}:INTERPOLATION:`
          );
          const network = this.stateService.network === 'liquid' || this.stateService.network === 'liquidtestnet' ? 'Liquid' : 'Bitcoin';
          const seoDescription = seoDescriptionNetwork(this.stateService.network);
          this.seoService.setDescription($localize`:@@meta.description.bitcoin.transaction:Get real-time status, addresses, fees, script info, and more for ${network}${seoDescription} transaction with txid ${this.txId}.`);
          this.resetTransaction();

          return merge(
            of(true),
            this.stateService.connectionState$.pipe(
              filter(
                (state) => state === 2 && this.tx && !this.tx.status?.confirmed
              )
            )
          );
        }),
        switchMap(() => {
          let transactionObservable$: Observable<Transaction>;
          const cached = this.cacheService.getTxFromCache(this.txId);
          if (cached && cached.fee !== -1) {
            transactionObservable$ = of(cached);
          } else {
            transactionObservable$ = this.electrsApiService
              .getTransaction$(this.txId)
              .pipe(
                catchError(this.handleLoadElectrsTransactionError.bind(this))
              );
          }
          return merge(
            transactionObservable$,
            this.stateService.mempoolTransactions$
          );
        }),
        switchMap((tx) => {
          if (this.network === 'liquid' || this.network === 'liquidtestnet') {
            return from(this.liquidUnblinding.checkUnblindedTx(tx))
              .pipe(
                catchError((error) => {
                  this.errorUnblinded = error;
                  return of(tx);
                })
              );
          }
          return of(tx);
        })
      ))
      .subscribe

this.stateService.fiatCurrency$.pipe(
            switchMap((currency) => {
              return tx.status.block_time ? this.priceService.getBlockPrice$(tx.status.block_time, true, currency).pipe(
                tap((price) => tx['price'] = price),
              ) : of(undefined);
            })
          ).subscribe

this.electrsApiService.getBlockHashFromHeight$(this.block.height)
      .pipe(
        switchMap((hash) => {
          return forkJoin([
            this.apiService.getBlock$(hash).pipe(
              catchError((err) => {
                console.error('Error fetching canonical block:', err);
                this.overviewError = err;
                return of(null);
              })
            ),
            this.apiService.getStrippedBlockTransactions$(hash).pipe(
              catchError((err) => {
                console.error('Error fetching canonical transactions:', err);
                this.overviewError = err;
                return of(null);
              })
            )
          ]);
        }),
        catchError((err) => {
          console.error('Error fetching canonical block hash:', err);
          return of([null, null]);
        })
      )
      .subscribe

